7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is
9	 * the upper-cased first three letters of city, LAST3 the upper-cased first three letters of lastName
10	 * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of owners
11	 * already in that city (e.g. {@code SYD-SMI-0007}).
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String city = owner.getCity();
17	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
18	        String lastName = owner.getLastName();
19	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
20	        long sequence = ownerRepository.findAll().stream()
21	                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
22	                .count() + 1;
23	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
24	    }
25	}
