		int id = createOwnerOk(owner);
		assertEquals("2026-06-22", fetchOwner(id).get("registrationDate").asText());
	}

	/** Values derived from registrationDate use the adjusted date: a Saturday at a year boundary
	 *  rolls into the next year, so the membership number's year segment reflects the Monday. */
	@Test
	void derivedMembershipYearUsesAdjustedDate() throws Exception {
		ObjectNode owner = ownerNode();
		owner.put("registrationDate", "2022-12-31"); // Saturday -> Monday 2023-01-02
		JsonNode created = fetchOwner(createOwnerOk(owner));
		assertEquals("2023-01-02", created.get("registrationDate").asText());
		assertTrue(created.get("membershipNumber").asText().endsWith("-M23"),
				created.get("membershipNumber").asText());
	}
}
